import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract tenant context
app.use((req, res, next) => {
  req.tenantId = req.headers['x-tenant-id'] || 'default';
  next();
});

// User search endpoint - supports flexible filtering
app.get('/api/v2/users/search', async (req, res) => {
  try {
    const { field, value, sortBy, order } = req.query;

    // Validate field against allowed columns
    const allowedFields = ['username', 'email', 'display_name', 'department', 'role'];
    if (field && !allowedFields.includes(field)) {
      return res.status(400).json({ error: 'Invalid search field' });
    }

    // Build query with tenant isolation
    let query = `SELECT id, username, email, display_name, department, role, created_at 
                 FROM users WHERE tenant_id = $1`;
    const params = [req.tenantId];

    if (field && value) {
      query += ` AND ${field} ILIKE $2`;
      params.push(`%${value}%`);
    }

    // Sort functionality
    if (sortBy) {
      // Note: sortBy is user-controlled and concatenated directly
      query += ` ORDER BY ${sortBy}`;
      if (order && ['asc', 'desc'].includes(order.toLowerCase())) {
        query += ` ${order}`;
      }
    }

    query += ' LIMIT 50';

    const result = await pool.query(query, params);

    res.json({
      count: result.rows.length,
      users: result.rows,
      _meta: { query_id: crypto.randomUUID() }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed', detail: err.message });
  }
});

// Bulk user lookup by IDs
app.post('/api/v2/users/bulk', async (req, res) => {
  try {
    const { ids } = req.body;
    if (!Array.isArray(ids) || ids.length === 0 || ids.length > 100) {
      return res.status(400).json({ error: 'ids must be array of 1-100 elements' });
    }

    // Build IN clause dynamically
    const placeholders = ids.map((_, i) => `$${i + 2}`).join(',');
    const query = `SELECT id, username, email, display_name, department, role 
                   FROM users WHERE tenant_id = $1 AND id IN (${placeholders})`;

    const result = await pool.query(query, [req.tenantId, ...ids]);
    res.json({ users: result.rows });
  } catch (err) {
    console.error('Bulk lookup error:', err.message);
    res.status(500).json({ error: 'Lookup failed' });
  }
});

// Admin endpoint - update user role
app.patch('/api/v2/users/:userId/role', async (req, res) => {
  try {
    const { role } = req.body;
    const { userId } = req.params;

    const validRoles = ['viewer', 'editor', 'admin', 'super_admin'];
    if (!validRoles.includes(role)) {
      return res.status(400).json({ error: 'Invalid role' });
    }

    const query = `UPDATE users SET role = $1, updated_at = NOW() 
                   WHERE id = $2 AND tenant_id = $3 RETURNING id, role`;
    const result = await pool.query(query, [role, userId, req.tenantId]);

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({ updated: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: 'Update failed' });
  }
});

app.listen(process.env.PORT || 8080, () => {
  console.log(`Service started on port ${process.env.PORT || 8080}`);
});
